282	
283	    /**
284	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city} or
285	     * {@code telephone} is missing or blank (including whitespace-only values that Bean Validation
286	     * does not catch). The names of all offending fields are collected so the caller receives a
287	     * 400 response whose {@code errors} array lists each one.
288	     */
289	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
290	        List<String> missingFields = new ArrayList<>();
291	        if (isBlank(ownerFieldsDto.getFirstName())) {
292	            missingFields.add("firstName");
293	        }
294	        if (isBlank(ownerFieldsDto.getLastName())) {
295	            missingFields.add("lastName");
296	        }
297	        if (isBlank(ownerFieldsDto.getAddress())) {
298	            missingFields.add("address");
299	        }
300	        if (isBlank(ownerFieldsDto.getCity())) {
301	            missingFields.add("city");
302	        }
303	        if (isBlank(ownerFieldsDto.getTelephone())) {
304	            missingFields.add("telephone");
305	        }
306	        if (!missingFields.isEmpty()) {
307	            throw new InvalidOwnerFieldsException(missingFields);
308	        }
309	    }
310	
311	    private static boolean isBlank(String value) {
312	        return value == null || value.trim().isEmpty();
313	    }
314	
315	    /**
316	     * Normalizes an owner's {@code address} on create and writes the canonical form back onto the
317	     * request so it is what gets validated, compared, stored and returned. The value is trimmed,
318	     * runs of internal whitespace are collapsed to a single space, the result is upper-cased and
319	     * common street-type abbreviations are expanded as whole tokens ({@code ST}->{@code STREET},
320	     * {@code RD}->{@code ROAD}, {@code AVE}->{@code AVENUE}). Running before the required-field check
321	     * means an address that is blank after normalization is rejected like a missing one.
322	     */
323	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
324	        ownerFieldsDto.setAddress(canonicalAddress(ownerFieldsDto.getAddress()));
325	    }
326	
327	    /**
328	     * Returns the canonical form of an address: trimmed, internal whitespace runs collapsed to a
329	     * single space, upper-cased, with common street-type abbreviations expanded as whole tokens. A
330	     * {@code null} value returns {@code null}. The transform is idempotent, so an already-canonical
331	     * address is returned unchanged, making it safe to apply to stored values during comparison.
332	     */
333	    private static String canonicalAddress(String address) {
334	        if (address == null) {
335	            return null;
336	        }
337	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
338	        if (collapsed.isEmpty()) {
339	            return "";
340	        }
341	        String[] tokens = collapsed.split(" ");
342	        StringBuilder sb = new StringBuilder(collapsed.length());
343	        for (int i = 0; i < tokens.length; i++) {
344	            if (i > 0) {
345	                sb.append(' ');
346	            }
347	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
348	        }
349	        return sb.toString();
350	    }
351	
352	    /**
353	     * Normalizes an owner's {@code telephone} on create into E.164 form. A leading {@code '+'} and
354	     * the country code that follows it are kept; otherwise the country code {@code '+61'} is assumed
355	     * and a single leading {@code '0'} is dropped from the national digits. Spaces, dashes and
356	     * brackets are stripped. The result must have 8 to 15 digits after the {@code '+'}. The E.164
357	     * string is written back onto the request so it is what gets stored and returned. Any value that
358	     * cannot form a valid E.164 number is rejected with a 400 response whose {@code errors} array
359	     * names {@code telephone}.
360	     */
361	    private void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
362	        ownerFieldsDto.setTelephone(toE164(ownerFieldsDto.getTelephone()));
363	    }
364	
365	    /**
366	     * Converts a raw telephone value to E.164 form, or throws {@link InvalidOwnerFieldsException}
367	     * (400) naming {@code telephone} when it cannot form a valid number.
368	     */
369	    private static String toE164(String telephone) {
370	        if (telephone == null) {
371	            throw new InvalidOwnerFieldsException(List.of("telephone"));
372	        }
373	        boolean hasCountryCode = telephone.trim().startsWith("+");
374	        String digits = telephone.replaceAll("\\D", "");
375	        String national;
376	        if (hasCountryCode) {
377	            national = digits;
378	        } else {
379	            if (digits.startsWith("0")) {
380	                digits = digits.substring(1);
381	            }
382	            national = "61" + digits;
383	        }
384	        if (!national.matches("[0-9]{8,15}")) {
385	            throw new InvalidOwnerFieldsException(List.of("telephone"));
386	        }
387	        return "+" + national;
388	    }
389	
390	    /**
391	     * Rejects creating an owner whose E.164 telephone is already used by any other owner. The
392	     * incoming value has already been converted to its E.164 form by {@link #normalizeTelephone};
393	     * each existing owner's stored telephone is converted the same way before comparison so numbers
394	     * that only differ in formatting still collide. A match results in a 409 response naming
395	     * {@code telephone}.
396	     */
397	    private void rejectDuplicateTelephone(OwnerFieldsDto ownerFieldsDto) {
398	        String telephone = ownerFieldsDto.getTelephone();
399	        for (Owner existing : this.clinicService.findAllOwners()) {
400	            if (telephone.equals(normalizeExisting(existing.getTelephone()))) {
401	                throw new DuplicateOwnerTelephoneException(telephone);
402	            }
403	        }
404	    }
405	
406	    /**
407	     * Returns the E.164 form of an already-stored telephone for duplicate comparison, or {@code null}
408	     * when the stored value cannot form a valid E.164 number (so it never matches an incoming one).
409	     */
410	    private static String normalizeExisting(String telephone) {
411	        try {
412	            return toE164(telephone);
413	        } catch (InvalidOwnerFieldsException ex) {
414	            return null;
415	        }
416	    }
417	
418	    /**
419	     * Rejects creating an owner whose {@code lastName} and {@code address} already belong to another
420	     * owner. Both fields are compared case-insensitively and with runs of whitespace collapsed to a
421	     * single space, so values that differ only in letter case or spacing still collide. When the
422	     * request opts in with {@code sharesHousehold} set to {@code true} the check is skipped, allowing
423	     * household members to share a name and address. A match results in a 409 response naming
424	     * {@code lastName} and {@code address}.
425	     */
426	    private void rejectDuplicateHousehold(OwnerFieldsDto ownerFieldsDto) {
427	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
428	            return;
429	        }
430	        String lastName = normalizeForComparison(ownerFieldsDto.getLastName());
431	        String address = canonicalAddress(ownerFieldsDto.getAddress());
432	        for (Owner existing : this.clinicService.findAllOwners()) {
433	            if (lastName.equals(normalizeForComparison(existing.getLastName()))
434	                && address.equals(canonicalAddress(existing.getAddress()))) {
435	                throw new DuplicateOwnerHouseholdException(
436	                    ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
437	            }
438	        }
439	    }
440	
441	    /**
442	     * Rejects creating an owner in a city that has reached capacity: a city that already contains
443	     * {@value #MAX_OWNERS_PER_CITY} or more owners cannot take another one. Existing owners are
444	     * counted with a case-insensitive match on {@code city}, the same way {@link #assignCustomerCode}
445	     * groups a city. A city at or over the limit results in a 409 response naming {@code city}.
446	     */
447	    private void rejectCityAtCapacity(OwnerFieldsDto ownerFieldsDto) {
448	        String city = ownerFieldsDto.getCity();
449	        int count = 0;
450	        for (Owner existing : this.clinicService.findAllOwners()) {
451	            if (city.equalsIgnoreCase(existing.getCity())) {
452	                count++;
453	            }
454	        }
455	        if (count >= MAX_OWNERS_PER_CITY) {
456	            throw new OwnerCityAtCapacityException(city);
457	        }
458	    }
459	
460	    /**
461	     * Rejects creating an owner once {@value #MAX_OWNERS_PER_DAY} or more owners already carry the
462	     * given adjusted business-day {@code registrationDate}, counted by an exact match. The date has
463	     * already been resolved and rolled forward off a weekend by {@link #resolveRegistrationDate}, so
464	     * the limit is enforced per business day. A day at or over the limit results in a 429 response.
465	     */
466	    private void rejectDailyLimitReached(LocalDate registrationDate) {
467	        int count = 0;
468	        for (Owner existing : this.clinicService.findAllOwners()) {
469	            if (registrationDate.equals(existing.getRegistrationDate())) {
470	                count++;
471	            }
472	        }
473	        if (count >= MAX_OWNERS_PER_DAY) {
474	            throw new DailyOwnerLimitReachedException(registrationDate);
475	        }
476	    }
477	
478	    /**
479	     * Normalizes a value for case-insensitive, whitespace-insensitive comparison: leading and
480	     * trailing whitespace is trimmed, internal runs of whitespace are collapsed to a single space and
481	     * the result is lower-cased. A {@code null} value normalizes to the empty string.
482	     */
483	    private static String normalizeForComparison(String value) {
484	        if (value == null) {
485	            return "";
486	        }
487	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
488	    }
489	
490	    /**
491	     * Normalizes an owner's optional {@code email}. The field may be omitted entirely, but when a
492	     * value is present it must be a syntactically valid address; the trimmed value is lower-cased and
493	     * written back onto the request so that is what gets stored and returned. A present but invalid
494	     * address is rejected with a 400 response whose {@code errors} array names {@code email}.
495	     */
496	    private void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
497	        String email = ownerFieldsDto.getEmail();
498	        if (email == null) {
499	            return;
500	        }
501	        String trimmed = email.trim();
502	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
503	            throw new InvalidOwnerFieldsException(List.of("email"));
504	        }
505	        ownerFieldsDto.setEmail(trimmed.toLowerCase(Locale.ROOT));
506	    }
507	
508	    /**
509	     * Rejects creating an owner whose email is already used by any other owner, compared on the
510	     * lower-cased form so addresses that differ only in letter case still collide. The incoming
511	     * value has already been trimmed and lower-cased by {@link #normalizeEmail}; each existing
512	     * owner's stored email is lower-cased the same way before comparison. Owners without an email
513	     * are ignored, and a request that supplies no email is never rejected. A match results in a
514	     * 409 response naming {@code email}.
515	     */
516	    private void rejectDuplicateEmail(OwnerFieldsDto ownerFieldsDto) {
517	        String email = ownerFieldsDto.getEmail();
518	        if (email == null) {
519	            return;
520	        }
521	        for (Owner existing : this.clinicService.findAllOwners()) {
522	            String existingEmail = existing.getEmail();
523	            if (existingEmail != null && email.equals(existingEmail.toLowerCase(Locale.ROOT))) {
524	                throw new DuplicateOwnerEmailException(email);
525	            }
526	        }
527	    }
528	
529	    /**
530	     * Resolves an owner's effective {@code registrationDate} on create and rolls it onto a business
531	     * day. When the caller supplies no value it defaults to the server's current date; a value
532	     * provided in the request is kept. The effective date, whether supplied or defaulted, must fall
533	     * on a business day: a Saturday or Sunday is rolled forward to the following Monday. The adjusted
534	     * date is written back onto the request so it is what gets stored and returned (in ISO
535	     * {@code YYYY-MM-DD} format) and what every value derived from the registration date is based on.
536	     */
537	    private void resolveRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
538	        LocalDate effective = ownerFieldsDto.getRegistrationDate();
539	        if (effective == null) {
540	            effective = LocalDate.now();
541	        }
542	        ownerFieldsDto.setRegistrationDate(toBusinessDay(effective));
543	    }
544	
545	    /**
546	     * Rolls a date forward onto a business day: a Saturday or Sunday is advanced to the following
547	     * Monday; a weekday is returned unchanged.
548	     */
549	    private static LocalDate toBusinessDay(LocalDate date) {
550	        return switch (date.getDayOfWeek()) {
551	            case SATURDAY -> date.plusDays(2);
552	            case SUNDAY -> date.plusDays(1);
553	            default -> date;
554	        };
555	    }
556	
557	    /**
558	     * Assigns the owner's {@code customerCode} on create, formatted {@code '<CITY3>-<LAST3>-<NNNN>'}
559	     * where {@code CITY3} is the upper-cased first three letters of {@code city}, {@code LAST3} is the
560	     * upper-cased first three letters of {@code lastName} and {@code NNNN} is a per-city 4-digit
561	     * zero-padded sequence equal to one more than the number of owners already in that city
562	     * (e.g. {@code 'SYD-SMI-0007'}).
563	     */
564	    private void assignCustomerCode(Owner owner) {
565	        String city = owner.getCity();
566	        String lastName = owner.getLastName();
567	        String cityPrefix = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
568	        String lastPrefix = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
569	        int sequence = 1;
570	        for (Owner existing : this.clinicService.findAllOwners()) {
571	            if (city.equalsIgnoreCase(existing.getCity())) {
572	                sequence++;
573	            }
574	        }
575	        owner.setCustomerCode(String.format("%s-%s-%04d", cityPrefix, lastPrefix, sequence));
576	    }
577	
578	    /**
579	     * Assigns the owner's {@code membershipNumber} on create, formatted
580	     * {@code '<customerCode>-M<YY>'} where {@code YY} is the last two digits of the
581	     * {@code registrationDate} year (e.g. {@code 'SMI-0007-M26'}). Assigned after
582	     * {@link #assignCustomerCode} and once {@code registrationDate} has been defaulted, so both
583	     * inputs are present.
584	     */
585	    private void assignMembershipNumber(Owner owner) {
586	        String yy = String.format("%02d", owner.getRegistrationDate().getYear() % 100);
587	        owner.setMembershipNumber(owner.getCustomerCode() + "-M" + yy);
588	    }
589	
590	    /**
591	     * Assigns the new owner's {@code namesakeCount} on create: the number of owners that already
592	     * exist sharing the same {@code firstName} and {@code lastName}, compared case-insensitively.
593	     * Computed before the new owner is persisted, so it counts only the pre-existing owners.
594	     */
595	    private void assignNamesakeCount(Owner owner) {
596	        String firstName = owner.getFirstName();
597	        String lastName = owner.getLastName();
598	        int count = 0;
599	        for (Owner existing : this.clinicService.findAllOwners()) {
600	            if (firstName.equalsIgnoreCase(existing.getFirstName())
601	                && lastName.equalsIgnoreCase(existing.getLastName())) {
602	                count++;
603	            }
604	        }
605	        owner.setNamesakeCount(count);
606	    }
607	
608	    /**
609	     * Assigns the new owner's {@code membershipLevel} on create: a number from 1 to 3 starting at
610	     * 1, plus 1 when an email is present, plus 1 when {@code namesakeCount} is 0, capped at 3.
611	     * Level 4 is reserved for tenure. Runs after {@link #assignNamesakeCount} so that count is
612	     * settled.
613	     */
614	    private void assignMembershipLevel(Owner owner) {
615	        int level = 1;
616	        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
617	            level++;
618	        }
619	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
620	            level++;
621	        }
622	        owner.setMembershipLevel(Math.min(level, 3));
623	    }
624	
625	    /**
626	     * Assigns the new owner's {@code bulkSignupWarning} on create: {@code true} when more than
627	     * {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry the new owner's adjusted
628	     * business-day {@code registrationDate}, otherwise {@code false}. Counted the same way as the
629	     * daily-limit rule and computed before the new owner is persisted, so it counts only the
630	     * pre-existing owners for that day.
631	     */
632	    private void assignBulkSignupWarning(Owner owner) {
633	        LocalDate registrationDate = owner.getRegistrationDate();
634	        int count = 0;
635	        for (Owner existing : this.clinicService.findAllOwners()) {
636	            if (registrationDate.equals(existing.getRegistrationDate())) {
637	                count++;
638	            }
639	        }
640	        owner.setBulkSignupWarning(count > BULK_SIGNUP_WARNING_THRESHOLD);
641	    }
642	
643	    /**
644	     * Assigns the new owner's {@code householdId} when the request opts in with
645	     * {@code sharesHousehold} set to {@code true} and at least one existing owner already shares the
646	     * same last name and address (compared case-insensitively with runs of whitespace collapsed, the
647	     * same way {@link #rejectDuplicateHousehold} matches). The household's members and the new owner
648	     * all end up carrying one stable shared identifier: if any existing member already has a
649	     * {@code householdId} it is reused, otherwise a new one is derived from the normalized last name
650	     * and address. Any existing member that is missing the identifier is updated so the whole
651	     * household stays consistent. When the flag is absent, or set but no matching owner exists, no
652	     * identifier is assigned.
653	     */
654	    private void assignHousehold(Owner owner, OwnerFieldsDto ownerFieldsDto) {
655	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
656	            return;
657	        }
658	        String lastName = normalizeForComparison(owner.getLastName());
659	        String address = canonicalAddress(owner.getAddress());
660	        List<Owner> members = new ArrayList<>();
661	        for (Owner existing : this.clinicService.findAllOwners()) {
662	            if (lastName.equals(normalizeForComparison(existing.getLastName()))
663	                && address.equals(canonicalAddress(existing.getAddress()))) {
664	                members.add(existing);
665	            }
666	        }
667	        if (members.isEmpty()) {
668	            return;
669	        }
670	        String householdId = members.stream()
671	            .map(Owner::getHouseholdId)
672	            .filter(id -> id != null && !id.isBlank())
673	            .findFirst()
674	            .orElseGet(() -> newHouseholdId(lastName, address));
675	        owner.setHouseholdId(householdId);
676	        for (Owner member : members) {
677	            if (!householdId.equals(member.getHouseholdId())) {
678	                member.setHouseholdId(householdId);
679	                this.clinicService.saveOwner(member);
680	            }
681	        }
682	    }
683	
684	    /**
685	     * Assigns the new owner's {@code householdMemberCount} on create: the number of owners sharing
686	     * the new owner's {@code householdId} once this create is applied — that is, the new owner plus
687	     * every existing owner already carrying the same identifier. Runs after {@link #assignHousehold}
688	     * so the identifier is settled. Left {@code null} when the owner belongs to no household.
689	     */
690	    private void assignHouseholdMembership(Owner owner) {
691	        String householdId = owner.getHouseholdId();
692	        if (householdId == null || householdId.isBlank()) {
693	            owner.setHouseholdMemberCount(null);
694	            return;
695	        }
696	        int count = 1;
697	        for (Owner existing : this.clinicService.findAllOwners()) {
698	            if (householdId.equals(existing.getHouseholdId())) {
699	                count++;
700	            }
701	        }
702	        owner.setHouseholdMemberCount(count);
703	    }
704	
705	    /**
706	     * Derives a stable household identifier from the normalized last name and address: the first
707	     * twelve upper-case hex characters of the SHA-256 digest of {@code "<lastName>|<address>"}. Two
708	     * owners in the same household therefore derive the same value regardless of creation order.
709	     */
710	    private static String newHouseholdId(String normalizedLastName, String normalizedAddress) {
711	        try {
712	            byte[] digest = MessageDigest.getInstance("SHA-256")
713	                .digest((normalizedLastName + "|" + normalizedAddress).getBytes(StandardCharsets.UTF_8));
714	            StringBuilder hex = new StringBuilder(digest.length * 2);
715	            for (byte b : digest) {
716	                hex.append(String.format("%02x", b));
717	            }
718	            return hex.substring(0, 12).toUpperCase(Locale.ROOT);
719	        } catch (NoSuchAlgorithmException ex) {
720	            throw new IllegalStateException("SHA-256 is required but unavailable", ex);
721	        }
722	    }
723	}
